set -eu
export PYTHONDONTWRITEBYTECODE=1
exec /home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3 - <<'PYREMOTE'
import base64,hashlib,json,os
from pathlib import Path
phase=Path('/home/loosqk/robot-checks/position-return-20261010-r1/head2-p32-trial-r14')
assert not (phase/'head2-p32-trial-r14').exists() and not (phase/'head2-p32-trial-launch-r14').exists()
items={'field_confirmation_r14.json': '', 'head2-p32-trial-r14.go.json': ''}
